// Verifies the HMAC signature Convex puts on every webhook.
// Signed string: `${X-LendLoop-Timestamp}.${raw body}`, key CONVEX_TO_N8N_SECRET.
// Uses the raw bytes (not re-serialised JSON) and a constant-time compare.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;

const secret = $env.CONVEX_TO_N8N_SECRET;
const headers = $input.first().json.headers ?? {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'] ?? '';

let raw = '';
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) {
  raw = '';
}

function check() {
  if (!secret) return 'secret not configured';
  if (!timestamp || !signature.startsWith('v1=')) return 'missing signature';
  const age = Math.abs(Date.now() / 1000 - Number(timestamp));
  if (!Number.isFinite(age) || age > MAX_SKEW_SECONDS) return 'stale timestamp';
  const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest();
  const given = Buffer.from(signature.slice(3), 'hex');
  if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) return 'signature mismatch';
  return null;
}

const problem = check();
if (problem) {
  console.log(`[lendloop] rejected webhook: ${problem}`);
  return [{ json: { valid: false, reason: problem } }];
}
return [{ json: { valid: true, event: JSON.parse(raw) } }];

// Builds the message from the minimum the webhook carries: first name, email,
// tool name, dates. Throws (and so reaches the error workflow) when the
// recipient cannot be notified.
const { event } = $('Verify signature').first().json;
const { eventId, type, loan, recipient } = event;
if (!recipient?.email) {
  throw new Error(`Recipient ${recipient?.userId ?? 'unknown'} has no email address; cannot notify about ${type} (${eventId})`);
}

const dates = loan.startDate === loan.endDate ? loan.startDate : `${loan.startDate} to ${loan.endDate}`;
const copy = {
  'loan.requested': ['New borrow request', `A neighbour would like to borrow your ${loan.toolName} (${dates}). Open LendLoop to approve or decline.`, 'Lender notified of a new request'],
  'loan.cancelled': ['Request cancelled', `The request to borrow your ${loan.toolName} (${dates}) was cancelled.`, 'Lender notified of the cancellation'],
  'loan.approved': ['Request approved', `Good news: your request for the ${loan.toolName} (${dates}) was approved. Please return it by ${loan.endDate}.`, 'Borrower notified of approval'],
  'loan.declined': ['Request declined', `Your request for the ${loan.toolName} (${dates}) was declined this time.`, 'Borrower notified of the decline'],
  'loan.returned': ['Thanks for returning it', `The ${loan.toolName} has been marked as returned. Thanks for keeping the loop going.`, 'Borrower notified of the return'],
}[type];
if (!copy) throw new Error(`Unknown event type ${type} (${eventId})`);

const [subject, text, summary] = copy;
return [{ json: { eventId, loanId: loan.id, to: recipient.email, firstName: recipient.firstName, subject, text: `Hi ${recipient.firstName}, ${text}`, summary } }];

// Mock delivery. A real provider call goes here (Resend, Postmark, SES...),
// passing `idempotencyKey` as the provider's Idempotency-Key header so a
// redelivered webhook cannot send the email twice.
const n = $input.first().json;
const masked = n.to.replace(/^(.).*(@.*)$/, '$1***$2');
const idempotencyKey = `notification:${n.eventId}`;
console.log(`[lendloop] MOCK EMAIL to=${masked} subject="${n.subject}" idempotency-key=${idempotencyKey}`);
return [{ json: { ...n, channel: 'email (mock)', idempotencyKey, sentAt: new Date().toISOString() } }];

// Signs a write-back for LendLoop's Convex endpoints: HMAC-SHA256 over
// `${timestamp}.${body}` with N8N_TO_CONVEX_SECRET (container env, never in this JSON).
const crypto = require('crypto');
function signForConvex(payload) {
  const secret = $env.N8N_TO_CONVEX_SECRET;
  if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set in the n8n container');
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const digest = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
  return { body, timestamp, signature: `v1=${digest}` };
}

const n = $input.first().json;
return [{ json: signForConvex({
  action: 'activity.record',
  idempotencyKey: n.idempotencyKey,        // notification:<eventId>, so retries and replays dedupe
  kind: 'notification_sent',
  loanId: n.loanId,
  summary: n.summary,
  workflow: $workflow.name,
  executionId: String($execution.id),
}) }];
